def packageDeliverySystem(truckCapacities, packageWeights):
    res = []
    for trucks, pkgs in zip(truckCapacities, packageWeights):
        caps = sorted(trucks, reverse=True)
        ps = sorted(pkgs, reverse=True)
        feasible = True
        i = 0  # truck index
        for w in ps:
            while i < len(caps) and caps[i] < w:
                i += 1
            if i >= len(caps):
                feasible = False; break
            caps[i] -= w
            # re-sort small section
            j = i
            while j + 1 < len(caps) and caps[j] < caps[j+1]:
                caps[j], caps[j+1] = caps[j+1], caps[j]
                j += 1
        res.append(1 if feasible else 0)
    return res

class Solution {
    public int[] packageDeliverySystem(int[][] truckCapacities, int[][] packageWeights) {
        int[] res = new int[truckCapacities.length];
        for (int s = 0; s < truckCapacities.length; s++) {
            java.util.PriorityQueue<Integer> pq = new java.util.PriorityQueue<>(java.util.Collections.reverseOrder());
            for (int c : truckCapacities[s]) pq.offer(c);
            Integer[] pkgs = java.util.stream.IntStream.of(packageWeights[s]).boxed().toArray(Integer[]::new);
            java.util.Arrays.sort(pkgs, java.util.Collections.reverseOrder());
            boolean ok = true;
            for (int w : pkgs) {
                if (pq.isEmpty() || pq.peek() < w) { ok = false; break; }
                int c = pq.poll();
                pq.offer(c - w);
            }
            res[s] = ok ? 1 : 0;
        }
        return res;
    }
}

class Solution {
public:
    vector<int> packageDeliverySystem(vector<vector<int>>& trucks, vector<vector<int>>& pkgs) {
        vector<int> res;
        for (int s = 0; s < (int)trucks.size(); s++) {
            priority_queue<int> pq(trucks[s].begin(), trucks[s].end());
            vector<int> p = pkgs[s];
            sort(p.begin(), p.end(), greater<int>());
            bool ok = true;
            for (int w : p) {
                if (pq.empty() || pq.top() < w) { ok = false; break; }
                int c = pq.top(); pq.pop();
                pq.push(c - w);
            }
            res.push_back(ok ? 1 : 0);
        }
        return res;
    }
};
